from fastapi import FastAPI, HTTPException, Depends, status
from fastapi.security import OAuth2PasswordBearer, OAuth2PasswordRequestForm
from sqlalchemy.orm import Session
from datetime import datetime, timedelta
import jwt
from typing import Optional, List
from config import settings
from model_config import UserCreate, UserUpdate, UserResponse, PollutionReport
from pydantic import EmailStr

app = FastAPI(title="CleanSignal API", version="1.0.0")

# Security
oauth2_scheme = OAuth2PasswordBearer(tokenUrl="/api/token")

# Mock database (will be replaced with SQLAlchemy models)
users_db = {
    "admin": {"username": "admin", "email": "admin@cleansignal.com", "password": "hashed", "is_active": True}
}
reports_db = []

# Token validation
def get_current_user(token: str = Depends(OAuth2PasswordBearer())):
    try:
        payload = jwt.decode(token, settings.SECRET_KEY, algorithms=[settings.ALGORITHM])
        username: str = payload.get("sub")
        if username is None:
            raise HTTPException(status_code=401, detail="Invalid token")
        return username
    except jwt.ExpiredSignatureError:
        raise HTTPException(status_code=401, detail="Token expired")
    except jwt.InvalidTokenError:
        raise HTTPException(status_code=401, detail="Invalid token")

# User endpoints
@app.post("/api/register", response_model=UserResponse)
def register_user(user: UserCreate):
    """Register a new user."""
    if user.username in users_db:
        raise HTTPException(status_code=400, detail="Username already exists")

    # In production, hash password here
    users_db[user.username] = {
        "username": user.username,
        "email": user.email,
        "password": user.password,
        "full_name": user.full_name,
        "is_active": True,
        "created_at": datetime.utcnow()
    }
    return {**users_db[user.username], "id": len(users_db) + 1}

@app.post("/api/login", response_model=dict)
def login(form: OAuth2PasswordRequestForm = Depends()):
    """Login and get access token."""
    user = users_db.get(form.username)
    if not user or user["password"] != form.password:
        raise HTTPException(
            status_code=401,
            detail="Incorrect username or password",
            headers={"WWW-Authenticate": "Bearer"}
        )

    access_token_expires = timedelta(minutes=settings.ACCESS_TOKEN_EXPIRE_MINUTES)
    access_token = jwt.encode({
        "sub": form.username,
        "exp": datetime.utcnow() + access_token_expires
    }, settings.SECRET_KEY, algorithm=settings.ALGORITHM)

    return {"access_token": access_token, "token_type": "bearer"}

# Pollution report endpoints
@app.post("/api/reports", response_model=dict)
def submit_report(report: PollutionReport, current_user: Optional[str] = Depends(get_current_user)):
    """Submit a new pollution report."""
    report_data = {
        "id": len(reports_db) + 1,
        **report.dict(),
        "timestamp": datetime.utcnow() if not report.timestamp else report.timestamp,
        "reporter_id": current_user if current_user else None
    }
    reports_db.append(report_data)
    return {"message": "Report submitted successfully", "report": report_data}

@app.get("/api/reports")
def get_reports(
    limit: int = 10,
    offset: int = 0,
    pollutant_type: Optional[str] = None,
    current_user: Optional[str] = Depends(get_current_user)
):
    """Get pollution reports with optional filtering."""
    filtered_reports = reports_db

    if pollutant_type:
        filtered_reports = [r for r in filtered_reports if r.get("pollutant_type") == pollutant_type]

    return {
        "reports": filtered_reports[offset:offset+limit],
        "total": len(filtered_reports),
        "limit": limit,
        "offset": offset
    }

@app.get("/api/reports/{report_id}")
def get_report(report_id: int):
    """Get a specific pollution report by ID."""
    report = next((r for r in reports_db if r["id"] == report_id), None)
    if not report:
        raise HTTPException(status_code=404, detail="Report not found")
    return report

@app.delete("/api/reports/{report_id}")
def delete_report(report_id: int, current_user: str = Depends(get_current_user)):
    """Delete a pollution report (only if user is the reporter)."""
    report = next((r for r in reports_db if r["id"] == report_id), None)
    if not report:
        raise HTTPException(status_code=404, detail="Report not found")

    if report.get("reporter_id") != current_user:
        raise HTTPException(status_code=403, detail="Not authorized to delete this report")

    reports_db.remove(report)
    return {"message": "Report deleted successfully"}

@app.get("/api/reports/search/{location}")
def search_reports(location: str):
    """Search reports by location."""
    filtered = [r for r in reports_db if location.lower() in r.get("location", "").lower()]
    return {"reports": filtered, "count": len(filtered)}

@app.get("/api/reports/urgent")
def get_urgent_reports():
    """Get high priority and urgent reports."""
    urgent = [r for r in reports_db if r.get("severity", 0) >= 4]
    return {"reports": urgent, "count": len(urgent)}

