.severity-1-2 { background: #c8e6c9; color: #2e7d32; }
.severity-3 { background: #fff9c4; color: #fbc02d; }
.severity-4-5 { background: #ffcdd2; color: #c62828; }

/* Footer */
footer {
    text-align: center;
    padding: 30px;
    color: white;
    opacity: 0.9;
}

/* Loading Spinner */
.spinner {
    border: 4px solid rgba(255,255,255,0.3);
    border-radius: 50%;
    border-top: 4px solid white;
    width: 40px;
    height: 40px;
    animation: spin 1s linear infinite;
    margin: 20px auto;
}

@keyframes spin {
    0% { transform: rotate(0deg); }
    100% { transform: rotate(360deg); }
}

/* Modal */
.modal {
    display: none;
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: rgba(0,0,0,0.5);
    justify-content: center;
    align-items: center;
    z-index: 1000;
