/* Responsive */
@media (max-width: 768px) {
    .form-row {
        grid-template-columns: 1fr;
    }

    header h1 {
        font-size: 2rem;
    }

    .navbar {
        flex-direction: column;
        gap: 15px;
    }
}

/* Success/Error Messages */
.success-message, .error-message {
    padding: 10px 15px;
    border-radius: 8px;
    margin-bottom: 15px;
    display: none;
}

.success-message {
    background: #c8e6c9;
    color: #2e7d32;
}

.error-message {
    background: #ffcdd2;
    color: #c62828;
}

